<?php declare(strict_types=1);if(!isset($documentTitle,$d,$items,$service)){http_response_code(404);exit;}$isRoute=$documentTitle==='Hoja de ruta';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($documentTitle)?> <?=e($isRoute?(string)$d['hojaRuta']:(string)$d['numeroRemito'])?></title><link rel="stylesheet" href="../assets/css/styles.css"></head><body class="print-page"><main class="print-document"><header><div><p>SEDEMA S.R.L.</p><h1><?=e($documentTitle)?></h1></div><strong><?=e($isRoute?(string)$d['hojaRuta']:(string)$d['numeroRemito'])?></strong></header><section class="print-meta"><div><span>Despacho</span><strong>#<?=(int)$d['idDespacho']?></strong></div><div><span>Pedido</span><strong>#<?=(int)$d['idPedido']?></strong></div><div><span>Programación</span><strong><?=e(date('d/m/Y H:i',strtotime((string)$d['fechaHoraProgramada'])))?></strong></div><div><span>Estado</span><strong><?=e($service->stateLabel((string)$d['estado']))?></strong></div></section><section class="print-address"><div><h2>Origen</h2><p><strong><?=e((string)$d['warehouseName'])?></strong><br><?=e((string)($d['warehouseAddress']?:'Sin domicilio registrado'))?></p></div><div><h2>Destino / cliente</h2><p><strong><?=e(trim((string)$d['clienteNombre']))?></strong><br><?=e((string)$d['destino'])?><br><?=e((string)($d['telefono']?:'Sin teléfono'))?></p></div></section><?php if($isRoute):?><section class="print-vehicle"><h2>Transporte</h2><p><?=e($d['matricula']?((string)$d['matricula'].' · '.$d['modelo']):'Retiro en corralón — sin vehículo asignado')?></p></section><?php endif;?><table><thead><tr><th>Código</th><th>Descripción</th><th>Cantidad</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e((string)$i['code'])?></td><td><?=e((string)$i['productName'])?></td><td><?=e($service->quantity((float)$i['cantidadADespachar']))?> <?=e((string)$i['symbol'])?></td></tr><?php endforeach;?></tbody></table><section class="print-notes"><h2>Observaciones</h2><p><?=e((string)($d['observacionesEntrega']?:'Sin observaciones.'))?></p></section><footer><div>Preparó / entregó</div><div>Recibí conforme</div><div>Aclaración / DNI</div></footer><button class="button button-primary print-button" type="button" data-print>Imprimir</button></main><script src="../assets/js/logistics.js"></script></body></html>
